import fs from "node:fs/promises";
import crypto from "node:crypto";

const OUT = "./";
const MORE = "./";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36";
const KW = /7\.4|7．4|璃月|加强|爆料|内鬼|emoji|表情/i;

async function connect() {
  const spaces = await listTaskSpaces();
  const entry = spaces && spaces[0];
  if (!entry) throw new Error("没有可用 task space");
  if (entry.ownership !== "user") return await taskSpace(entry.id);
  try { return await takeOverTaskSpace(entry.id); } catch { return await claimTaskSpace(entry.id); }
}

const ts = await connect();
await fs.mkdir(MORE, { recursive: true });
let page = (await ts.pages()).find((p) => /tieba|baidu/i.test((p && p.label) || ""));
if (!page) page = (await ts.pages())[0];
if (!page) throw new Error("拿不到 page 句柄");

// 已存在的图（判断是否“新图”）
const existing = new Map();
for (const f of await fs.readdir(MORE).catch(() => [])) {
  try {
    const b = await fs.readFile(MORE + f);
    existing.set(crypto.createHash("sha256").update(b).digest("hex"), f);
  } catch {}
}

const strip = (s) => s.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&quot;/g, '"')
  .replace(/\s+/g, " ").trim();

function parseCands(html) {
  const out = new Map();
  for (const m of html.matchAll(/<a[^>]+href="\/p\/(\d{8,})"[^>]*?(?:title="([^"]{2,140})")?[^>]*>/g)) {
    const tid = m[1], title = (m[2] || "").trim();
    if (!out.has(tid) || (title && title.length > (out.get(tid).title || "").length)) out.set(tid, { tid, title });
  }
  for (const m of html.matchAll(/\/p\/(\d{8,})/g)) {
    const tid = m[1];
    if (out.has(tid) && out.get(tid).title) continue;
    const ctx = strip(html.slice(Math.max(0, m.index - 700), m.index + 250));
    if (!out.has(tid)) out.set(tid, { tid, title: "", ctx });
    else if (!out.get(tid).ctx) out.get(tid).ctx = ctx;
  }
  return [...out.values()].map((x) => ({ tid: x.tid, title: (x.title || "").slice(0, 120), ctx: (x.ctx || "").slice(0, 200) }));
}

async function grab(url, waitMs) {
  let err = null;
  try { await page.goto(url, { waitUntil: "domcontentloaded", timeout: 45000 }); } catch (e) { err = String(e).slice(0, 120); }
  await sleep(waitMs);
  const r = await page.evaluate(() => ({
    url: location.href, title: document.title,
    txt: (document.body ? document.body.innerText || "" : "").slice(0, 60000),
    html: document.documentElement.outerHTML,
  }));
  return { ...r, err };
}

const BASE = "http./";
const queries = [
  { id: "s1", url: BASE + encodeURIComponent("原神 7.4 璃月 加强") },
  { id: "s2", url: BASE + encodeURIComponent("璃月 加强 emoji") },
  { id: "s3", url: BASE + encodeURIComponent("钟离 刻晴 加强 爆料") },
  { id: "bar", url: "http./" + encodeURIComponent("原神内鬼吧") + "&ie=utf-8&pn=0" },
];

const steps = [];
const cands = new Map();
for (const q of queries) {
  const S = await grab(q.url, 8500);
  const list = parseCands(S.html);
  const hits = list.filter((c) => KW.test(c.title) || KW.test(c.ctx || ""));
  steps.push({ id: q.id, url: q.url, title: S.title, len: S.txt.length, blocked: /安全验证|请输入验证码/.test(S.txt), nCand: list.length, nHit: hits.length, err: S.err });
  await fs.writeFile(OUT + "neigui-02-" + q.id + ".txt", S.txt, "utf8");
  for (const h of hits) {
    const old = cands.get(h.tid);
    if (!old || (h.title || "").length > (old.title || "").length) cands.set(h.tid, { ...h, q: q.id });
  }
  console.log("[" + q.id + "] cand=" + list.length + " hit=" + hits.length + " blocked=" + /安全验证|请输入验证码/.test(S.txt));
  for (const h of hits.slice(0, 10)) console.log("   " + h.tid + " | " + h.title + " | " + (h.ctx || "").slice(0, 70));
}

// 选帖：优先标题同时含 7.4 与（璃月|加强）
const all = [...cands.values()];
const strong = all.filter((c) => /7\.4/.test(c.title) && /璃月|加强/.test(c.title));
const pick = (strong.length ? strong : all).slice(0, 3);

const threads = [];
const images = [];
let seq = 0;
for (const c of pick) {
  const url = "http./" + c.tid;
  const D = await grab(url, 6500);
  const detail = await page.evaluate(() => {
    const urls = new Set();
    const push = (v) => { if (v && typeof v === "string" && /tiebapic|hiphotos|bdimg/.test(v)) urls.add(v.replace(/^\/\//, "http./")); };
    for (const im of document.images) for (const k of ["src", "data-original", "bpic", "data-src", "data-url"]) push(im.getAttribute(k) || (k === "src" ? im.src : ""));
    for (const m of document.documentElement.outerHTML.matchAll(/https?:\/\/[^"'\s\\)]*tiebapic[^"'\s\\)]*/g)) push(m[0]);
    const floors = [...document.querySelectorAll(".l_post")].map((el, i) => ({ n: i + 1, t: (el.innerText || "").replace(/\n{2,}/g, "\n").trim().slice(0, 700) }));
    const txt = document.body ? document.body.innerText || "" : "";
    const emojiLines = txt.split("\n").map((s) => s.trim())
      .filter((s) => s && /\p{Extended_Pictographic}|[★☆●○▲△□■◆◇]|🀄|🃏/u.test(s)).slice(0, 60);
    return { imgs: [...urls], floors: floors.slice(0, 40), emojiLines, txt: txt.slice(0, 40000), title: document.title };
  });
  await fs.writeFile(OUT + "thread-" + c.tid + ".txt", detail.txt, "utf8");

  const got = [];
  for (const u of detail.imgs) {
    seq += 1;
    const nn = String(seq).padStart(2, "0");
    const name = "贴吧-" + c.tid + "-" + nn + ".png";
    const path = MORE + name;
    let buf = null;
    try {
      const r = await fetch(u, { headers: { Referer: "http./", "User-Agent": UA } });
      if (r.ok) buf = Buffer.from(await r.arrayBuffer());
    } catch {}
    if (!buf || buf.length < 1000) {
      try {
        const b64 = await page.evaluate(async (src) => {
          try {
            const r = await fetch(src, { credentials: "include" });
            if (!r.ok) return "ER./" + r.status;
            const ab = await r.arrayBuffer(); const bytes = new Uint8Array(ab);
            let bin = ""; for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
            return "O./" + btoa(bin);
          } catch (e) { return "ER./" + String(e).slice(0, 60); }
        }, u);
        if (typeof b64 === "string" && b64.startsWith("O./")) buf = Buffer.from(b64.slice(3), "base64");
      } catch {}
    }
    if (!buf || buf.length < 1000) continue;
    const sha = crypto.createHash("sha256").update(buf).digest("hex");
    await fs.writeFile(path, buf);
    const rec = { file: path, src: u, bytes: buf.length, sha12: sha.slice(0, 12), tid: c.tid, dupOf: existing.get(sha) || null };
    images.push(rec); got.push(rec);
  }
  threads.push({ tid: c.tid, url, title: detail.title, nImg: detail.imgs.length, got: got.length, floors: detail.floors, emojiLines: detail.emojiLines, head: detail.txt.slice(0, 1500) });
  console.log("THREAD " + c.tid + " | " + detail.title.slice(0, 60) + " | img=" + detail.imgs.length + " got=" + got.length);
