Get-ChildItem "$more\*.png" | ForEach-Object {
  $b=[System.IO.File]::ReadAllBytes($_.FullName)
  $ext = if($b[0] -eq 0xFF -and $b[1] -eq 0xD8){'jpg'} elseif($b[0] -eq 0x89 -and $b[1] -eq 0x50){'png'} elseif($b[0] -eq 0x52 -and $b[1] -eq 0x49){'webp'} elseif($b[0] -eq 0x47){'gif'} else {'bin'}
  $dims=''
  if($ext -eq 'png'){ $w=[int]$b[16]*16777216+[int]$b[17]*65536+[int]$b[18]*256+[int]$b[19]; $h=[int]$b[20]*16777216+[int]$b[21]*65536+[int]$b[22]*256+[int]$b[23]; $dims="${w}x${h}" }
  $new=[System.IO.Path]::ChangeExtension($_.FullName,$ext)
  if($new -ne $_.FullName){ Move-Item -LiteralPath $_.FullName -Destination $new -Force }
  if($_.Length -gt 40000){ "{0}  {1}B  {2}  {3}" -f [System.IO.Path]::GetFileName($new),$_.Length,$ext,$dims }
}
"--- KEYWORD LINES ---"
foreach($f in @('thread-11053191596.txt','thread-11210499193.txt')){
  "##### $f"
  $t=Get-Content "./" -Raw -Encoding UTF8
  $ms=[regex]::Matches($t,'[^\n]*(钟离|刻晴|烟绯|重云|凝光)[^\n]*')
  $ms | Select-Object -First 8 | ForEach-Object { '  > ' + $_.Value.Substring(0,[Math]::Min(230,$_.Value.Length)) }
}","description":"按魔数改名并抽取角色解读原句"}

